WITH lines AS (SELECT id, customer_id, created_at, attr_key, attr_value FROM carts LATERAL VIEW EXPLODE(attributes) li AS attr_key, attr_value) SELECT customer_id, DATE_TRUNC('DAY', created_at) AS activity_day, SORT_ARRAY(COLLECT_SET(attr_key)) AS attr_key_list, SORT_ARRAY(COLLECT_SET(attr_key)) AS attr_key_list_2 FROM lines GROUP BY ROLLUP (customer_id, DATE_TRUNC('DAY', created_at))
